package data_structures.hashing;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class HashTable {
public static class Table<K,V> implements Iterable<Map.Entry<K,V>>{private List<List<Map.Entry<K,V>>> buckets;private int count;private final ToLongFunction<K> hasher;private final double maxLoadFactor;public Table(){this(Hash::defaultHasher,16,.75);}public Table(ToLongFunction<K> h,int capacity,double factor){hasher=h;maxLoadFactor=factor;buckets=create(Math.max(1,capacity));}private List<List<Map.Entry<K,V>>> create(int n){List<List<Map.Entry<K,V>>> b=new ArrayList<>();for(int i=0;i<n;i++)b.add(new ArrayList<>());return b;}private List<Map.Entry<K,V>> bucket(K k){return buckets.get((int)Math.floorMod(hasher.applyAsLong(k),buckets.size()));}public int size(){return count;}public int capacity(){return buckets.size();}public Table<K,V> set(K k,V v){List<Map.Entry<K,V>> b=bucket(k);for(var e:b)if(Objects.equals(e.getKey(),k)){e.setValue(v);return this;}b.add(new AbstractMap.SimpleEntry<>(k,v));count++;if((double)count/buckets.size()>maxLoadFactor)resize(buckets.size()*2);return this;}public V get(K k){for(var e:bucket(k))if(Objects.equals(e.getKey(),k))return e.getValue();return null;}public boolean has(K k){for(var e:bucket(k))if(Objects.equals(e.getKey(),k))return true;return false;}public boolean delete(K k){var b=bucket(k);for(int i=0;i<b.size();i++)if(Objects.equals(b.get(i).getKey(),k)){b.remove(i);count--;return true;}return false;}public void clear(){buckets=create(buckets.size());count=0;}private void resize(int n){List<Map.Entry<K,V>> a=new ArrayList<>();for(var e:this)a.add(e);buckets=create(n);for(var e:a)bucket(e.getKey()).add(e);}public Iterable<K> keys(){List<K> o=new ArrayList<>();for(var e:this)o.add(e.getKey());return o;}public Iterable<V> values(){List<V> o=new ArrayList<>();for(var e:this)o.add(e.getValue());return o;}public Iterator<Map.Entry<K,V>> iterator(){List<Map.Entry<K,V>> o=new ArrayList<>();for(var b:buckets)for(var e:b)o.add(new AbstractMap.SimpleEntry<>(e));return o.iterator();}}
}
